using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public sealed class MotionParityInput:MonoBehaviour,ITrainingInputSource,ITrainingResettableInputSource {public Vector2 move;public bool dash,pulse,jump;public TrainingInputFrame ReadInput(){var f=new TrainingInputFrame{Movement=move,Dash=dash,DashPressed=pulse,Commands=jump?new[]{TrainingCommand.Jump}:new TrainingCommand[0]};pulse=jump=false;return f;}public void Clear(){move=Vector2.zero;dash=pulse=jump=false;}}
[InitializeOnLoad]public static class MotionParityChecks {
 const string Pending="MotionParityQA";static List<string> rows;static TrainingFighter a,b;static MotionParityInput sa,sb;static int stage,count,orientation=1;static long start;static float xa,xb,ya,yb,peakA,peakB;static string report,sourceBytes;static double deadline;
 static MotionParityChecks(){if(SessionState.GetBool(Pending,false))EditorApplication.update+=Tick;}
 public static void Run(){if(EditorApplication.isPlaying)throw new Exception("Fresh verification required");EditorSceneManager.OpenScene(TrainingFlowSession.TrainingScene);SessionState.SetBool(Pending,true);EditorApplication.update-=Tick;EditorApplication.update+=Tick;EditorApplication.EnterPlaymode();}
 static void C(bool value,string text){if(!value)throw new Exception(text);rows.Add("PASS "+text);count++;}static bool Near(float x,float y)=>Mathf.Abs(x-y)<.0002f;static bool Elapsed(int n)=>a.InputBuffer.Frame-start>=n;
 static void Begin(int s){stage=s;start=a.InputBuffer.Frame;}
 static void Reset(float spacing=5){sa.Clear();sb.Clear();a.ResetTraining();b.ResetTraining();a.GetComponent<TrainingMotor2D>().Teleport(new Vector2(-orientation*spacing,.01f));b.GetComponent<TrainingMotor2D>().Teleport(new Vector2(orientation*spacing,.01f));a.RefreshTrainingFacing();b.RefreshTrainingFacing();xa=a.transform.position.x;xb=b.transform.position.x;ya=a.transform.position.y;yb=b.transform.position.y;}
 static void Setup(){rows=new List<string>();var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"-parityReport");report=i<0?"Temp/parity.txt":args[i+1];deadline=EditorApplication.timeSinceStartup+120;var hud=UnityEngine.Object.FindAnyObjectByType<TrainingOverlay>();a=hud.player;b=a.opponent;hud.Session.enabled=false;a.TrainingSession=b.TrainingSession=null;a.CameraBounds=b.CameraBounds=null;sa=a.gameObject.AddComponent<MotionParityInput>();sb=b.gameObject.AddComponent<MotionParityInput>();a.SetInputSource(sa);b.SetInputSource(sb);var ta=a.GetComponent<ApprovedLocomotionTuning>();var tb=b.GetComponent<ApprovedLocomotionTuning>();C(a.GetComponents<ApprovedLocomotionTuning>().Length==1&&b.GetComponents<ApprovedLocomotionTuning>().Length==1,"exactly one canonical applicator per fighter");C(ta.canonicalProfile==tb.canonicalProfile,"same persistent canonical motion SO");C(JsonUtility.ToJson(ta.Applied)==JsonUtility.ToJson(tb.Applied),"same applied movement settings");C(!ReferenceEquals(a.definition,b.definition),"independent mutable runtime character copies");foreach(string name in new[]{"walkSpeed","dashSpeed","acceleration","dashDeceleration","backstepSpeed","backstepSeconds","jumpVelocity","gravity","takeoffSeconds","landingSeconds","crouchHeight","crouchTransitionSeconds"}){var field=typeof(TrainingCharacterDefinition).GetField(name);C(Equals(field.GetValue(a.definition),field.GetValue(b.definition)),"matching effective "+name);}C(Near(a.definition.backstepSpeed,3.6f)&&Near(a.definition.backstepSeconds,25f/60-.000001f),"adopted backstep25F 1.5m retained");C(Near(a.gravity,-8f*2/(.9f*.9f))&&Near(a.jumpVelocity,4f*2/.9f-.5f*a.gravity/60),"adopted jump54F height2m retained");C(a.airDashProfile==b.airDashProfile,"existing shared air dash settings retained");sourceBytes=File.ReadAllText(AssetDatabase.GetAssetPath(ta.canonicalProfile));Reset();Begin(0);}
 static void Pair(string phase){rows.Add("MEASURE "+phase+" frame="+(a.InputBuffer.Frame-start)+" travelA="+Mathf.Abs(a.transform.position.x-xa)+" travelB="+Mathf.Abs(b.transform.position.x-xb));C(Near(Mathf.Abs(a.HorizontalVelocity),Mathf.Abs(b.HorizontalVelocity)),phase+" mirrored horizontal velocity");C(Near(a.VerticalVelocity,b.VerticalVelocity)&&Near(a.transform.position.y,b.transform.position.y),phase+" vertical state");C(Near(Mathf.Abs(a.transform.position.x-xa),Mathf.Abs(b.transform.position.x-xb)),phase+" displacement parity");}
 static void Tick(){try{if(!EditorApplication.isPlaying||Time.frameCount<5)return;if(rows==null){Setup();return;}if(EditorApplication.timeSinceStartup>deadline)throw new Exception("Parity timeout stage "+stage);if(stage==0&&Elapsed(3)){C(a.Facing==orientation&&b.Facing==-orientation,"facing remains opponent-relative "+orientation);sa.move=new Vector2(orientation,0);sb.move=-sa.move;Begin(1);}else if(stage==1&&Elapsed(12)){Pair("walk "+orientation);C(Near(Mathf.Abs(a.HorizontalVelocity),a.walkSpeed),"walk reaches unchanged3.5m/s");sa.dash=sb.dash=true;Begin(2);}else if(stage==2&&Elapsed(16)){Pair("dash "+orientation);C(Near(Mathf.Abs(a.HorizontalVelocity),a.dashSpeed),"dash reaches unchanged6m/s");sa.Clear();sb.Clear();Begin(3);}else if(stage==3&&Elapsed(8)){Pair("dash release "+orientation);Reset(3);Begin(4);}else if(stage==4&&Elapsed(3)){sa.move=new Vector2(-orientation,0);sb.move=-sa.move;sa.pulse=sb.pulse=true;xa=a.transform.position.x;xb=b.transform.position.x;Begin(5);}else if(stage==5&&Elapsed(3)){C(a.CurrentPhase==TrainingFighter.Phase.Backstep&&b.CurrentPhase==TrainingFighter.Phase.Backstep,"both backsteps start");Pair("backstep "+orientation);sa.move=sb.move=Vector2.zero;Begin(6);}else if(stage==6&&Elapsed(27)){C(a.CurrentPhase==TrainingFighter.Phase.Idle&&b.CurrentPhase==TrainingFighter.Phase.Idle,"both backsteps return idle");Pair("backstep end "+orientation);C(Mathf.Abs(Mathf.Abs(a.transform.position.x-xa)-1.5f)<.07f,"backstep measured1.5m");Reset(3);Begin(7);}else if(stage==7&&Elapsed(3)){ya=a.transform.position.y;yb=b.transform.position.y;peakA=peakB=0;sa.jump=sb.jump=true;Begin(8);}else if(stage==8){peakA=Mathf.Max(peakA,a.transform.position.y-ya);peakB=Mathf.Max(peakB,b.transform.position.y-yb);if(a.CurrentPhase!=b.CurrentPhase||!Near(a.VerticalVelocity,b.VerticalVelocity)||!Near(a.transform.position.y,b.transform.position.y))throw new Exception("Jump phase/velocity parity failure");if(Elapsed(85)){C(a.IsGrounded&&b.IsGrounded,"both jump trajectories land");C(Near(peakA,peakB)&&Mathf.Abs(peakA-2)<.08f,"same observed jump peak near2m");rows.Add("MEASURE orientation="+orientation+" peak="+peakA+" gravity="+a.gravity+" jumpVelocity="+a.jumpVelocity);if(orientation==1){orientation=-1;Reset();Begin(0);}else{C(File.ReadAllText(AssetDatabase.GetAssetPath(a.GetComponent<ApprovedLocomotionTuning>().canonicalProfile))==sourceBytes,"Play leaves adopted motion SO unchanged");Finish(0);}}}}
 catch(Exception e){rows?.Add("FAIL "+e);Debug.LogException(e);Finish(1);}}
 static void Finish(int exit){SessionState.SetBool(Pending,false);EditorApplication.update-=Tick;rows?.Add(count+" PASS; exit="+exit+"; scripted logical sources, not physical keyboard/pad");if(rows!=null)File.WriteAllLines(report,rows);EditorApplication.Exit(exit);}
}
